'use strict';
let readingIndexCache=null,readingOriginalCache=null,librarySearchType='all',librarySearchPage=1,librarySearchLast='';
const readingTypes=[['all','全部编选内容'],['event','纪事'],['person','人物'],['work','著作'],['guide','主题导读'],['network','思想关系'],['place','地点'],['term','术语'],['original','原始笔记 · 独立检索']];
const READING_PAGE_SIZE=24;
function readingNormalize(value){return String(value||'').normalize('NFKC').toLocaleLowerCase();}
function readingSearchText(entry){return readingNormalize([entry.title,entry.name,entry.role,entry.summary,entry.originalTitle,entry.genre,entry.dateLabel,entry.publicationLabel,typeof entry.argument==='string'?entry.argument:'',entry.misreading?.claim,entry.misreading?.correction,...(entry.aliases||[]),...(entry.people||[]),...(entry.works||[]),...(entry.keyTerms||[]).flatMap(t=>[t.term,t.definition]),...(entry.positions||[]).flatMap(p=>[p.name,p.claim,p.limit]),...(entry.sections||[]).flatMap(s=>[s.title,s.text]),...(entry.passages||[]).flatMap(p=>[p.locator,p.prompt])].join(' '));}
function readingDate(entry){if(entry.dateLabel)return entry.dateLabel;if(entry.lifeLabel)return entry.lifeLabel;if(Number.isFinite(entry.year))return entry.endYear&&entry.endYear!==entry.year?cultureRange([entry.year,entry.endYear]):cultureYear(entry.year);if(entry.range)return cultureRange(entry.range);return '';}
function readingRecord(kind,entry,type){return {key:kind+':'+entry.id,kind,id:entry.id,type,title:entry.title||entry.name,summary:entry.summary||entry.sections?.[0]?.text||(typeof entry.argument==='string'?entry.argument:''),date:type==='guide'&&entry.range?'阅读范围 '+cultureRange(entry.range):type==='place'&&entry.range?'沿革范围 '+cultureRange(entry.range):readingDate(entry),text:readingSearchText(entry),entry};}
function readingIndex(){
 if(readingIndexCache)return readingIndexCache;
 const records=[],cultureIds=new Set((comparisonReaderData.cultureEvents||[]).map(e=>e.id));
 for(const entry of readerEvents())if(!cultureIds.has(entry.id))records.push(readingRecord('events',entry,'event'));
 for(const [key,kind,type] of [['people','people','person'],['essays','essays','guide'],['places','places','place'],['terms','terms','term'],['cultureEvents','culture','event'],['culturePrehistory','culture','guide'],['cultureTraditions','culture','guide'],['cultureQuestions','culture','guide'],['cultureWorks','culture','work']])for(const entry of comparisonReaderData[key]||[])records.push(readingRecord(kind,entry,type));
 const personIds=new Set((comparisonReaderData.cultureNetworkLanes||[]).flatMap(l=>l.personIds));
 for(const id of personIds){const person=comparisonReaderData.people.find(p=>p.id===id),entity=cultureEntity('network-'+id);if(!entity||!person)continue;const relations=(comparisonReaderData.cultureRelations||[]).filter(r=>r.fromId===id||r.toId===id);records.push(readingRecord('culture',{...entity,dateLabel:person.lifeLabel+' · 人物生平',people:[person.name],summary:'查看'+person.name+'的学习、文本接受及思想回应，逐条阅读关系与出处。',sections:relations.map(r=>({title:r.title,text:r.summary}))},'network'));}
 if(typeof philosophyAtlasData!=='undefined')for(const node of philosophyAtlasData.nodes||[])if(!node.readRef)records.push(readingRecord('philosophy',node,node.kind==='event'?'event':node.kind));
 readingIndexCache=records;return records;
}
function readingOriginalIndex(){if(!readingOriginalCache)readingOriginalCache=philosophyTreeData.nodes.map(node=>({...readingRecord('culture',node,'original'),text:readingNormalize(treeSearchText(node)),summary:node.title,date:`原主题 ${node.order} · ${treeReviewMap.has(node.id)?'初步辨析':'待审核'}`}));return readingOriginalCache;}
function readingFind(kind,id){return readingIndex().find(r=>r.kind===kind&&r.id===id)||(kind==='events'?readingIndex().find(r=>r.kind==='culture'&&r.id===id&&r.type==='event'):null)||(kind==='culture'&&id.startsWith('tree-')?readingOriginalIndex().find(r=>r.id===id):null);}
function readingMatches(record,query){const tokens=readingNormalize(query).trim().split(/\s+/).filter(Boolean);return tokens.every(token=>record.text.includes(token));}
function readingScore(record,query){const term=readingNormalize(query).trim(),tokens=term.split(/\s+/),title=readingNormalize(record.title),original=readingNormalize(record.entry.originalTitle);let score=1;if(record.type==='person'&&title.includes(term))score+=20;if(title===term||original===term)score+=100;else if(title.includes(term)||original.includes(term))score+=50;if(tokens.every(t=>title.includes(t)||original.includes(t)))score+=30;score+=tokens.filter(t=>title.includes(t)).length*8;if((record.entry.aliases||[]).some(a=>readingNormalize(a)===term))score+=30;if((record.entry.people||[]).some(p=>readingNormalize(p).includes(term)))score+=12;if(readingNormalize(record.summary).includes(term))score+=5;if(record.type==='original'&&treeFigureMap.get(record.entry.figureId)?.primaryNodeId===record.id)score+=8;return score+20/(title.length+1);}
function readingResults(query,type='all'){const source=type==='original'?readingOriginalIndex():readingIndex();return source.filter(r=>(type==='all'||r.type===type)&&readingMatches(r,query)).map(record=>({record,score:readingScore(record,query)})).sort((a,b)=>b.score-a.score||a.record.key.localeCompare(b.record.key)).map(item=>item.record);}
function readingExcerpt(record,query){const term=readingNormalize(query).trim(),tokens=term.split(/\s+/).filter(Boolean),texts=[record.summary,...(record.entry.sections||[]).map(s=>s.text)].filter(Boolean);let text=texts.find(t=>readingNormalize(t).includes(term))||texts.find(t=>tokens.some(token=>readingNormalize(t).includes(token)))||record.summary||'打开条目查看完整内容、关联资料及出处。';if(record.type==='original'&&!tokens.some(token=>readingNormalize(text).includes(token)))text='主题路径：'+treeAncestors(record.entry).map(n=>n.title).join(' / ');const normalized=readingNormalize(text),match=normalized.indexOf(term),start=match>60?match-35:0;return (start?'…':'')+text.slice(start,start+155)+(text.length>start+155?'…':'');}
function readingAreaFor(kind,id,previous='history'){if(kind==='philosophy')return 'culture';if(kind==='culture')return id.startsWith('tree-')?'archive':'culture';if(['events','essays','places'].includes(kind))return 'history';if(['history','culture'].includes(previous))return previous;const person=kind==='people'?comparisonReaderData.people.find(p=>p.id===id):null;return person?.side==='china'?'history':'culture';}
function readingTarget(value){if(typeof value!=='string'||value.length>160)return null;const match=/^(events|people|essays|places|terms|culture|philosophy):([a-z0-9-]+)$/.exec(value);if(!match)return null;const record=readingFind(match[1],match[2]);return record?{kind:record.kind,id:record.id}:null;}
function readingLink(kind,id,base=location.href){const record=readingFind(kind,id);if(!record)return null;const url=new URL(base);if(record.kind==='philosophy'){url.searchParams.set('section','philosophy');url.searchParams.set('phEntry',record.id);url.searchParams.set('phYear',record.entry.anchor);}url.searchParams.set('read',record.key);url.searchParams.set('readArea',readingAreaFor(record.kind,record.id,readerArea));return url.href;}
function openReadingRecord(kind,id){const record=readingFind(kind,id);if(!record)return;if(record.kind==='philosophy'){$('#comparison-reader-dialog').close();openPhilosophyAtlas({entry:record.id,fromReader:true});return;}readerArea=readingAreaFor(record.kind,record.id,'search');focusReaderEntity(record.kind,record.id);}
function restoreReadingLink(value,area=null){const target=readingTarget(value);if(!target)return false;if(target.kind==='philosophy'){openPhilosophyAtlas({entry:target.id});return true;}openComparisonReader(target.kind==='culture'?'culture':'events');readerArea=readingAreaFor(target.kind,target.id,['history','culture','archive'].includes(area)?area:'search');focusReaderEntity(target.kind,target.id);const url=new URL(location.href);url.searchParams.set('read',target.kind+':'+target.id);url.searchParams.set('readArea',readerArea);history.replaceState(null,'',url);return true;}
function openLibrarySearch(){librarySearchType='all';librarySearchPage=1;librarySetMode('search');$('#reader-settings').open=true;$('#reader-search').focus();}
function readingTypeLabel(type){return readingTypes.find(t=>t[0]===type)?.[1]||'阅读资料';}
function renderLibrarySearch(root,query){
 const controls=historyEl('div',null,'reading-search-controls'),label=historyEl('label','资料类型 '),select=historyEl('select');select.id='library-search-type';for(const [id,title] of readingTypes.filter(([id])=>id!=='original'||!philosophyTreeData.publication))select.append(new Option(title,id));select.value=librarySearchType;select.addEventListener('change',()=>{librarySearchType=select.value;librarySearchPage=1;renderComparisonReader();$('#library-search-type').focus({preventScroll:true});});label.append(select);controls.append(label,historyEl('small',philosophyTreeData.publication?.notice||'编选内容跨栏目检索；原始笔记单独列出，保留原文及核验状态。'));root.append(controls);
 const signature=librarySearchType+'|'+query;if(signature!==librarySearchLast){librarySearchPage=1;librarySearchLast=signature;}
 if(!query.trim()){const empty=historyEl('section',null,'reading-search-intro');empty.append(historyEl('h3','用一个关键词，连接不同的阅读入口。'),historyEl('p','查找人物、作品、纪事、地点和思想问题。检索结果保留各自的实际年代，打开条目后可用“返回”回到这次检索。'));const examples=historyEl('div',null,'reading-search-examples');for(const word of ['苏格拉底','共相','文艺复兴','笛卡尔'])examples.append(libraryButton(word,()=>{$('#reader-search').value=word;renderComparisonReader();$('#reader-search').focus();}));empty.append(examples);root.append(empty);return 0;}
 const results=readingResults(query,librarySearchType),pages=Math.max(1,Math.ceil(results.length/READING_PAGE_SIZE));librarySearchPage=Math.max(1,Math.min(librarySearchPage,pages));const status=historyEl('p',`${results.length} 条匹配 · 第 ${librarySearchPage}/${pages} 页 · 每页 ${READING_PAGE_SIZE} 条`,'reading-search-count');status.id='library-search-count';status.setAttribute('role','status');root.append(status);
 const list=historyEl('div',null,'reading-search-list');for(const record of results.slice((librarySearchPage-1)*READING_PAGE_SIZE,librarySearchPage*READING_PAGE_SIZE)){const card=historyEl('article',null,'reading-search-result');card.dataset.readingKey=record.key;card.dataset.readingType=record.type;card.append(historyEl('p',readingTypeLabel(record.type)+(record.date?' · '+record.date:''),'reader-entry-meta'));const button=libraryButton(record.title.length>100?record.title.slice(0,100)+'…':record.title,()=>openReadingRecord(record.kind,record.id),'reading-result-title');const heading=historyEl('h3');heading.append(button);card.append(heading);card.append(historyEl('p',readingExcerpt(record,query)));list.append(card);}root.append(list);
 if(!results.length){root.append(historyEl('p',philosophyTreeData.publication?'没有匹配的编选资料。可以缩短关键词或调整资料类型。':'没有匹配的编选资料。可以缩短关键词、调整资料类型，或单独查找原始笔记。','reader-empty'));if(librarySearchType!=='original'&&!philosophyTreeData.publication)root.append(libraryButton('用相同关键词查原始笔记 →',()=>{librarySearchType='original';librarySearchPage=1;renderComparisonReader();}));}
 if(pages>1){const pager=historyEl('nav',null,'reading-search-pager');pager.setAttribute('aria-label','检索结果翻页');for(const [label,step] of [['← 上一页',-1],['下一页 →',1]]){const button=libraryButton(label,()=>{librarySearchPage+=step;renderComparisonReader();$('#library-search-count').scrollIntoView({block:'start'});});button.disabled=step<0?librarySearchPage===1:librarySearchPage===pages;pager.append(button);}root.append(pager);}return results.length;
}
function readingCardRecord(card){for(const [attribute,kind] of [['readerCulture','culture'],['readerEntry','events'],['readerPerson','people'],['readerEssay','essays'],['readerPlace','places'],['readerTerm','terms']])if(card.dataset[attribute])return readingFind(kind,card.dataset[attribute]);return null;}
async function copyReadingLink(record,bar){const value=readingLink(record.kind,record.id);if(!value)return;let status=bar.querySelector('.reading-action-status');if(!status){status=historyEl('span',null,'reading-action-status');status.setAttribute('role','status');bar.append(status);}try{await navigator.clipboard.writeText(value);status.textContent='阅读链接已复制';}catch{status.textContent='可选中下方链接复制';let field=bar.querySelector('input');if(!field){field=historyEl('input');field.type='text';field.readOnly=true;field.setAttribute('aria-label','当前条目的阅读链接');bar.append(field);}field.value=value;field.focus();field.select();}}
function unifyReadingCards(root){
 for(const card of root.querySelectorAll('article.reader-entry')){const record=readingCardRecord(card);if(!record)continue;card.dataset.readingKey=record.key;const badge=historyEl('p',null,'reading-kind-label');badge.textContent=record.type==='original'?'原始笔记 · '+(treeReviewMap.has(record.id)?'初步辨析':'待审核'):record.type==='event'?(record.id.startsWith('acts-')?'经文纪事':record.kind==='culture'?'文化纪事':'历史纪事'):readingTypeLabel(record.type)+' · 编者整理';card.prepend(badge);
  let bookmark=card.querySelector('[data-reading-action="bookmark"]');if(!bookmark){bookmark=readerSaveButton(record.kind,record.id);(card.querySelector('.reader-entry-body')||card).append(bookmark);}if(bookmark&&!bookmark.closest('.reading-common-actions')){const bar=historyEl('div',null,'reading-common-actions');bookmark.replaceWith(bar);bar.append(bookmark);const share=libraryButton('复制阅读链接',()=>copyReadingLink(record,bar),'reading-share');share.dataset.readingAction='share';bar.append(share);}
 }
}
function readingMapContext(){if(typeof isPhilosophyView==='function'&&isPhilosophyView())return `哲学时间轴停留在${philosophyDate(philosophyState.year)}`;return typeof isOT==='function'&&isOT()?`主图保持旧约经文进度（第 ${state.year} 节点）`:`地图仍停留在公元 ${readerYear} 年`;}
function renderReadingUnity(){
 const search=readerTab==='culture'&&readerCultureMode==='search',context=$('#library-reading-context');
 context.textContent=search?'全库检索 · 跨栏目、跨年代 · 主图进度保持不变':readerArea==='archive'?'原始资料 · 原文与新增辨析分别呈现':['people','terms'].includes(readerTab)?`${readerTab==='people'?'人物生平':'术语释义'} · 跨年代资料 · ${readingMapContext()}`:readerTab==='culture'&&readerCultureMode!=='chronology'?`跨年代阅读 · ${readingMapContext()}`:(()=>{const bounds=readerBounds($('#reader-period').value),full=$('#reader-full-period').checked;return `编年范围 ${bounds[0]}—${bounds[1]} 年 · ${full?'显示整段':'截至浏览 '+readerYear+' 年'}`;})();
 context.hidden=readerTab==='culture'&&readerCultureMode==='overview';$('#reader-window-note').hidden=true;$('#library-universal-search').setAttribute('aria-pressed',String(search));
 if(search){$('#reader-title').textContent='全库检索';$('.reader-intro').textContent='统一查找人物、著作、纪事与主题，沿资料的实际关联继续阅读。';$('#library-location').textContent='阅读中心 / 全库检索';$('#library-menu>summary').textContent='阅读导航 · 全库检索';$('#library-culture-nav').hidden=true;$('#library-history-nav').hidden=true;document.querySelectorAll('.library-area-nav>button').forEach(b=>b.setAttribute('aria-pressed','false'));$('#reader-search').placeholder='检索全部编选内容，如：笛卡尔 怀疑';$('#reader-results').textContent=($('#library-search-count')?.textContent||'输入关键词开始全库检索');}
 $('#reader-results').closest('.reader-result-row').hidden=search;if(search)$('#reader-index').hidden=true;unifyReadingCards($('#reader-content'));
}
function bindReadingUnity(){$('#library-universal-search').addEventListener('click',openLibrarySearch);}
